/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(classStr(PriceDisc))]
final class AVAPriceDisc_Extension
{
    public boolean  avaGraduatedPrice;
    public FromDate costingVersionFromDate;
    public ToDate   costingVersionToDate;
    public PriceDiscTable       avaPriceDiscTable;
}

Method.Source:
/// <summary>
/// desigend from AVA
/// </summary>
/// <param name = "_relation">_relation</param>
/// <param name = "_inventDimId">_inventDimId</param>
/// <param name = "_itemCode">_itemCode</param>
/// <param name = "_itemRelation">_itemRelation</param>
/// <param name = "_accountCode">_accountCode</param>
/// <param name = "_accountRelation">_accountRelation</param>
/// <param name = "_unitId">_unitId</param>
/// <returns>Query</returns>
protected internal Query buildFindPriceDiscountQuery(PriceType    _relation,
                          InventDimId           _inventDimId,
                          PriceDiscProductCodeType _itemCode,
                          ItemId                _itemRelation,
                          PriceDiscPartyCodeType _accountCode,
                          CustVendAC            _accountRelation,
                          UnitOfMeasureSymbol   _unitId)
{

    Query query = next buildFindPriceDiscountQuery(_relation,_inventDimId,_itemCode,_itemRelation,_accountCode,_accountRelation,_unitId);

    if (avaGraduatedPrice)
    {
        if (!EcoResProductParameters::find().AVAtest)
        {
            boolean cacheMode = (_itemCode != PriceDiscProductCodeType::Table || _accountCode != PriceDiscPartyCodeType::Table)
                && !this.parmMCRPriceHistoryPotentialCalc();
            if (cacheMode)
            {
                SysGlobalObjectCache    SysGlobalObjectCache  = new SysGlobalObjectCache();
                SysGlobalObjectCache.clear('PriceDisc:FindPrice');
            }
        }
        query.dataSourceTable(tableNum(PriceDiscTable)).sortClear();
     //   query.dataSourceTable(tableNum(PriceDiscTable)).addRange(fieldNum(PriceDiscTable,AVAGraduatedPrice)).value(any2str(avaGraduatedPrice));
        query.dataSourceTable(tableNum(PriceDiscTable)).addOrderByField(fieldNum(PriceDiscTable,AVAGraduatedPrice),SortOrder::Descending);
        query.dataSourceTable(tableNum(PriceDiscTable)).addOrderByField(fieldNum(PriceDiscTable,FromDate),SortOrder::Ascending);
      /*  query.dataSourceTable(tableNum(PriceDiscTable)).addRange(fieldNum(PriceDiscTable,Recid)).value(strFmt('(((%1.%2 >= %3) && ((%1.%2 <= %4) || (%4 == %5))) || ((%1.%6 >= %3) && ((%1.%6 <= %4) || (%4 == %5))))',
                                                                                                       query.dataSourceTable(tableNum(PriceDiscTable)).name(),
                                                                                                       fieldStr(PriceDiscTable,FromDate),
                                                                                                       Date2StrXpp(costingVersionFromDate),
                                                                                                       date2StrXpp(costingVersionToDate),
                                                                                                       date2StrXpp(dateNull()),
                                                                                                       fieldStr(PriceDiscTable,ToDate)));*/


    }      

    return query;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_avaGraduaredPrice">_avaGraduaredPrice</param>
/// <returns>_avaGraduaredPrice</returns>
public boolean parmAVAGraduatedPrice(AVAGraduatedPrice     _avaGraduaredPrice)
{
    avaGraduatedPrice   = _avaGraduaredPrice;
    return avaGraduatedPrice;
}

/// <summary>
///  designed from AVA
/// </summary>
/// <param name = "_costingVersionFromDate">_costingVersionFromDate</param>
/// <returns>FromDate</returns>
public FromDate parmCostingVersionFromDate(FromDate  _costingVersionFromDate = costingVersionFromDate)
{
    costingVersionFromDate  = _costingVersionFromDate;
    return costingVersionFromDate;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_costingVersionToDate">_costingVersionToDate</param>
/// <returns>toDate</returns>
public ToDate   parmCostingVersionToDate(ToDate   _costingVersionToDate = costingVersionToDate)
{
    costingVersionToDate = _costingVersionToDate;
    return costingVersionToDate;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>PriceDiscPriceAgreementSearchParameters</returns>
protected PriceDiscPriceAgreementSearchParameters instantiatePriceDiscPriceAgreementSearchParameters()
{
    PriceDiscPriceAgreementSearchParameters priceDiscPriceAgreementSearchParameters = next instantiatePriceDiscPriceAgreementSearchParameters();
    priceDiscPriceAgreementSearchParameters.parmAVAGraduatedPrice(avaGraduatedPrice);
    priceDiscPriceAgreementSearchParameters.parmItemId(priceDiscParameters.parmItemId());
    return priceDiscPriceAgreementSearchParameters;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>PriceCur</returns>
public PriceCur  price()
{
    Price       locPrice = next price();

    if (avaGraduatedPrice == NoYes::Yes && avaPriceDiscTable.AVAGraduatedPrice == NoYes::Yes)
    {
        locPrice = CurrencyExchangeHelper::price(avaPriceDiscTable.AVACalcChargeAmount(), priceDiscParameters.parmCurrencyCode());
    }

    return locPrice;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_priceDiscTable">_priceDiscTable</param>
/// <param name = "_priceType">_priceType</param>
public void calculatePriceAgreement(PriceDiscTable _priceDiscTable, PriceType _priceType)
{
    avaPriceDiscTable = _priceDiscTable.data();
    next calculatePriceAgreement(_priceDiscTable,_priceType);
}
